/** Every article of the blog, newest first. */
export const BLOG_POSTS: readonly BlogPost[] = [
  {
    slug: 'bacteria-wars-turn-relay',
    published: '2026-11-20',
    title: {
      en: 'Through the wall: how Bacteria Wars relays online matches through TURN',
      de: 'Durch die Wand: wie Bacteria Wars Online-Matches über TURN weiterleitet',
    },
    summary: {
      en: 'Two phones on mobile data could not play each other. What NATs do to peer-to-peer WebRTC, what STUN and TURN are, and how the game wires Cloudflare’s TURN relay in without calling a single function.',
      de: 'Zwei Handys im Mobilfunknetz konnten nicht gegeneinander spielen. Was NATs mit Peer-to-Peer-WebRTC machen, was STUN und TURN sind und wie das Spiel Cloudflares TURN-Relay anbindet, ohne eine einzige Funktion aufzurufen.',
    },
    loadComponent: () =>
      import('./posts/bacteria-wars-turn-relay/turn-relay-post.component').then(
        (m) => m.TurnRelayPostComponent
      ),
  },
];

/** The post of a slug, if there is one. */
export function findBlogPost(slug: string): BlogPost | undefined {
  return BLOG_POSTS.find((post) => post.slug === slug);
}
  ChangeDetectionStrategy,
  Component,
  computed,
  DOCUMENT,
  inject,
  input,
  OnInit,
} from '@angular/core';

const JSON_LD_ID = 'blog-post-json-ld';

/**
 * The frame every article shares: date, title and lead from its
 * {@link BlogPost}, its `BlogPosting` data in the head, the article's own
 * text projected in, and the links back.
 */
@Component({
  selector: 'wolsok-blog-article',
  imports: [RouterLink, MatButtonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <header class="article-head">
      <p class="eyebrow">
        <a routerLink="/blog">{{ t().blog.eyebrow }}</a>
        ·
        <time [attr.datetime]="post().published">{{ published() }}</time>
      </p>
      <h1>{{ i18n.pick(post().title) }}</h1>
      <p class="lead">{{ i18n.pick(post().summary) }}</p>
    </header>
    <ng-content />
    <footer class="article-foot">
      <a matButton="outlined" routerLink="/blog">← {{ t().blog.back }}</a>
      @if (playUrl(); as url) {
        <a matButton="filled" [href]="url">{{ t().blog.playGame }}</a>
      }
    </footer>
  `,
  styleUrl: './blog-page.scss',
})
export class BlogArticleComponent implements OnInit {
  public readonly post = input.required<BlogPost>();
  /** The game the article is about, linked at its end. */
  public readonly playUrl = input<string>();

  protected readonly i18n = inject(I18nService);
  protected readonly t = this.i18n.texts;
  private readonly document = inject(DOCUMENT);

  protected readonly published = computed(() =>
    this.i18n.fill(this.t().blog.published, {
      date: publishedOn(this.post(), this.i18n.locale()),
    })
  );

  public ngOnInit(): void {
    let script = this.document.getElementById(JSON_LD_ID);
    if (!script) {
      script = this.document.createElement('script');
      script.id = JSON_LD_ID;
      script.setAttribute('type', 'application/ld+json');
      this.document.head.appendChild(script);
    }
    script.textContent = blogPostingJsonLd(this.post(), SITE_URL);
  }
}

/** What an article's route carries: its page data and the post itself. */
export interface BlogPostRouteData extends PageData {
  post: BlogPost;
}

const BLOG_INDEX: Route = {
  path: 'blog',
  loadComponent: () =>
    import('./blog-index.component').then((m) => m.BlogIndexComponent),
  data: {
    title: {
      en: 'Blog – Wolfram Sokollek',
      de: 'Blog – Wolfram Sokollek',
    },
    description: {
      en: 'Articles by Wolfram Sokollek on how his games and apps work under the hood: WebRTC, NAT traversal, GPU simulations, Angular and the cloud.',
      de: 'Artikel von Wolfram Sokollek darüber, wie seine Spiele und Apps unter der Haube funktionieren: WebRTC, NAT-Traversal, GPU-Simulationen, Angular und die Cloud.',
    },
  } satisfies PageData,
};

function postRoute(post: BlogPost): Route {
  return {
    path: `blog/${post.slug}`,
    loadComponent: post.loadComponent,
    data: {
      title: {
        en: `${post.title.en} – wolsok.de`,
        de: `${post.title.de} – wolsok.de`,
      },
      description: post.summary,
      post,
    } satisfies BlogPostRouteData,
  };
}

/** The blog's index and one page per post. */
export const blogRoutes: Route[] = [BLOG_INDEX, ...BLOG_POSTS.map(postRoute)];
<section class="hero" aria-labelledby="blog-heading">
  <p class="eyebrow">{{ t().blog.eyebrow }}</p>
  <h1 id="blog-heading">
    {{ t().blog.title }} <em>{{ t().blog.titleAccent }}</em>
  </h1>
  <p class="lead">{{ t().blog.lead }}</p>
</section>

<section class="posts">
  @for (post of posts; track post.slug) {
    <article class="post-card">
      <p class="date">
        <time [attr.datetime]="post.published">{{ published(post) }}</time>
      </p>
      <h2>
        <a [routerLink]="path(post)">{{ i18n.pick(post.title) }}</a>
      </h2>
      <p class="summary">{{ i18n.pick(post.summary) }}</p>
      <span class="read" aria-hidden="true">{{ t().blog.read }} →</span>
    </article>
  }
</section>

/**
 * The `BlogPosting` schema.org data of a post, for search engines: in
 * English, the language the pages are prerendered in.
 */
export function blogPostingJsonLd(post: BlogPost, siteUrl: string): string {
  const url = siteUrl + blogPostPath(post);
